-- (Keep your existing audit_logs alters here...)
-- This block fixes schema differences found during the first deployment attempt.
create table if not exists public.audit_logs (
  id uuid primary key default gen_random_uuid(),
  actor_uid uuid,
  actor_role text,
  action text,
  table_name text,
  row_id text,
  old_record jsonb,
  new_record jsonb,
  created_at timestamptz default now()
);

alter table if exists public.audit_logs
  add column if not exists actor_uid uuid,
  add column if not exists actor_role text,
  add column if not exists action text,
  add column if not exists table_name text,
  add column if not exists row_id text,
  add column if not exists old_record jsonb,
  add column if not exists new_record jsonb,
  add column if not exists created_at timestamptz default now();

do $be_preflight$
begin
  if to_regclass('public.staff_master') is not null then
    alter table public.staff_master add column if not exists name text;
    alter table public.staff_master add column if not exists email text;
    alter table public.staff_master add column if not exists type text default 'staff';
    alter table public.staff_master add column if not exists vehicle_type text;
    alter table public.staff_master add column if not exists vehicle_plate text;
    alter table public.staff_master add column if not exists helper_name text;
    alter table public.staff_master add column if not exists status text default 'active';
    alter table public.staff_master add column if not exists created_at timestamptz default now();
    alter table public.staff_master add column if not exists updated_at timestamptz default now();
    update public.staff_master
       set name = coalesce(nullif(name, ''), nullif(email, ''), 'staff-' || id::text),
           type = coalesce(nullif(type, ''), 'staff'),
           status = coalesce(nullif(status, ''), 'active')
     where name is null or name = '' or type is null or type = '' or status is null or status = '';
  end if;

  if to_regclass('public.branch_offices') is not null then
    alter table public.branch_offices add column if not exists code text;
    alter table public.branch_offices add column if not exists name text;
    alter table public.branch_offices add column if not exists city text;
    alter table public.branch_offices add column if not exists status text default 'active';
    alter table public.branch_offices add column if not exists created_at timestamptz default now();
    update public.branch_offices
       set name = coalesce(nullif(name, ''), 'Branch ' || id::text),
           code = coalesce(nullif(code, ''), upper(left(regexp_replace(coalesce(nullif(name, ''), id::text), '[^a-zA-Z0-9]+', '', 'g'), 12))),
           status = coalesce(nullif(status, ''), 'active')
     where name is null or name = '' or code is null or code = '' or status is null or status = '';
  end if;
end
$be_preflight$;



-- ---------- Foundational compatibility tables ----------
create table if not exists public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  role text not null default 'data_entry',
  full_name text not null default '',
  email text not null default '',
  phone text,
  zone text,
  status text not null default 'active',
  created_at timestamptz default now(),
  updated_at timestamptz default now()
);

create table if not exists public.shipments (
  id uuid primary key default gen_random_uuid(),
  tracking_no text not null,
  customer_name text not null default '',
  customer_phone text,
  pickup_address text,
  delivery_address text not null default '',
  township text,
  zone text,
  status text not null default 'created',
  assigned_to uuid,
  assigned_to_name text,
  cod_amount numeric(12,2) default 0,
  service_type text default 'standard',
  weight numeric(8,2),
  merchant_id uuid,
  merchant_name text,
  priority boolean default false,
  notes text,
  proof_photo_url text,
  delivered_at timestamptz,
  created_at timestamptz default now(),
  updated_at timestamptz default now()
);
create unique index if not exists shipments_tracking_no_uidx on public.shipments (tracking_no);

create table if not exists public.cod_collections (
  id uuid primary key default gen_random_uuid(),
  tracking_no text,
  shipment_id uuid,
  rider_id uuid,
  driver_id uuid,
  assigned_to uuid,
  user_id uuid,
  rider_name text,
  amount numeric(12,2) not null default 0,
  status text not null default 'pending',
  collected_at timestamptz,
  handover_status text not null default 'pending',
  handover_at timestamptz,
  settlement_ref text,
  notes text,
  created_at timestamptz default now()
);
alter table public.cod_collections add column if not exists rider_name text;
alter table public.cod_collections add column if not exists assigned_to uuid;
alter table public.cod_collections add column if not exists user_id uuid;
alter table public.cod_collections add column if not exists driver_id uuid;
alter table public.cod_collections add column if not exists handover_status text default 'pending';
alter table public.cod_collections add column if not exists handover_at timestamptz;
alter table public.cod_collections add column if not exists settlement_ref text;


-- ---------- Role helpers ----------
create or replace function public.be_current_role()
returns text
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(
    (select lower(replace(p.role, '-', '_')) from public.profiles p where p.id = auth.uid()),
    lower(replace(auth.jwt() ->> 'role', '-', '_')),
    lower(replace(auth.jwt() ->> 'app_role', '-', '_')),
    ''
  );
$$;

create or replace function public.be_has_role(allowed text[])
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select public.be_current_role() = any(allowed)
     or coalesce(auth.jwt() ->> 'email','') in ('md@britiumexpress.com','sai@britiumexpress.com');
$$;

