  name text not null,
  phone text,
  address text,
  status text not null default 'active',
  created_at timestamptz default now(),
  updated_at timestamptz default now()
);
alter table public.merchants add column if not exists merchant_code text;
alter table public.merchants add column if not exists phone text;
alter table public.merchants add column if not exists address text;
alter table public.merchants add column if not exists status text default 'active';
create unique index if not exists merchants_name_uidx on public.merchants (name);
create unique index if not exists merchants_code_uidx on public.merchants (merchant_code) where merchant_code is not null;

create table if not exists public.townships (
  id uuid primary key default gen_random_uuid(),
