-- ---------- Pickup/order workflow ----------
create table if not exists public.pickups (
  id uuid primary key default gen_random_uuid(),
  pickup_code text not null,
  pickup_date date,
  merchant_id uuid references public.merchants(id),
  merchant_name text,
  status text not null default 'ready_for_data_entry',
  created_by uuid references auth.users(id),
  pickup_by text,
  total_items int default 0,
  total_cod numeric(12,2) default 0,
  total_delivery_fee numeric(12,2) default 0,
  total_actual_collect numeric(12,2) default 0,
  source_file text,
  created_at timestamptz default now(),
  updated_at timestamptz default now()
);
create unique index if not exists pickups_code_uidx on public.pickups (pickup_code);
create index if not exists pickups_status_idx on public.pickups (status);
create index if not exists pickups_merchant_idx on public.pickups (merchant_name);

