-- ---------- Remove known demo/sample operational records from earlier builds ----------
-- Unified Demo & Partial-Import Cleanup (Parser-Safe)
do $$
begin

  -- 1. delivery_process_events
  begin
    execute 'delete from public.delivery_process_events where tracking_no in (select s.tracking_no from public.shipments s where coalesce(s.source_file,'''') = ''BE_MasterData_April.xlsx'' or coalesce(s.source_file,'''') ilike ''%demo%'' or s.tracking_no like ''BX-2026-%'' or s.tracking_no ilike ''DEMO%'') or tracking_no like ''BX-2026-%'' or tracking_no ilike ''DEMO%''';
  exception when others then null;
  end;

  -- 2. route_stops
  begin
    execute 'delete from public.route_stops rs using public.shipments s where rs.shipment_id = s.id and (coalesce(s.source_file,'''') = ''BE_MasterData_April.xlsx'' or coalesce(s.source_file,'''') ilike ''%demo%'' or s.tracking_no like ''BX-2026-%'' or s.tracking_no ilike ''DEMO%'' or s.merchant_name in (''Golden Shop'',''Silver Store'',''Diamond Mart'',''Tech Store Myanmar'',''Fashion Hub'',''Book World'',''Demo Merchant''))';
  exception when others then
    begin
      execute 'delete from public.route_stops where tracking_no like ''BX-2026-%'' or tracking_no ilike ''DEMO%'' or tracking_no in (select tracking_no from public.shipments where coalesce(source_file,'''') = ''BE_MasterData_April.xlsx'')';
    exception when others then null;
    end;
  end;

  -- 3. delivery_proofs
  begin
    execute 'delete from public.delivery_proofs dp using public.shipments s where dp.shipment_id = s.id and (coalesce(s.source_file,'''') = ''BE_MasterData_April.xlsx'' or coalesce(s.source_file,'''') ilike ''%demo%'' or s.tracking_no like ''BX-2026-%'' or s.tracking_no ilike ''DEMO%'' or s.merchant_name in (''Golden Shop'',''Silver Store'',''Diamond Mart'',''Tech Store Myanmar'',''Fashion Hub'',''Book World'',''Demo Merchant''))';
  exception when others then null;
  end;

  -- 4. delivery_exceptions
  begin
    execute 'delete from public.delivery_exceptions de using public.shipments s where de.shipment_id = s.id and (coalesce(s.source_file,'''') = ''BE_MasterData_April.xlsx'' or coalesce(s.source_file,'''') ilike ''%demo%'' or s.tracking_no like ''BX-2026-%'' or s.tracking_no ilike ''DEMO%'' or s.merchant_name in (''Golden Shop'',''Silver Store'',''Diamond Mart'',''Tech Store Myanmar'',''Fashion Hub'',''Book World'',''Demo Merchant''))';
  exception when others then null;
  end;

  -- 5. cod_collections
  begin
    execute 'delete from public.cod_collections where tracking_no in (select tracking_no from public.shipments where coalesce(source_file,'''') = ''BE_MasterData_April.xlsx'' or coalesce(source_file,'''') ilike ''%demo%'' or tracking_no like ''BX-2026-%'' or tracking_no ilike ''DEMO%'') or tracking_no like ''BX-2026-%'' or tracking_no ilike ''DEMO%''';
  exception when others then
    begin
      execute 'delete from public.cod_collections where coalesce(rider_name,'''') ilike ''%demo%''';
    exception when others then null;
    end;
  end;

  -- 6. pickup_attachments_2026_04_24 (Rider App)
  begin
    execute 'delete from public.pickup_attachments_2026_04_24 where pickup_id like ''PU-%'' or pickup_id ilike ''%demo%''';
  exception when others then null;
  end;

  -- 7. pickups_2026_04_24 (Rider App)
  begin
    execute 'delete from public.pickups_2026_04_24 where pickup_id like ''PU-%'' or pickup_id ilike ''%demo%''';
  exception when others then
    begin
      execute 'delete from public.pickups_2026_04_24 where coalesce(remarks,'''') ilike ''%demo%'' or coalesce(remarks,'''') ilike ''%BE_MasterData_April.xlsx%''';
    exception when others then null;
    end;
  end;

  -- 8. shipments
  begin
    execute 'delete from public.shipments where coalesce(source_file,'''') = ''BE_MasterData_April.xlsx'' or coalesce(source_file,'''') ilike ''%demo%'' or tracking_no like ''BX-2026-%'' or tracking_no ilike ''DEMO%'' or merchant_name in (''Golden Shop'',''Silver Store'',''Diamond Mart'',''Tech Store Myanmar'',''Fashion Hub'',''Book World'',''Demo Merchant'')';
  exception when others then null;
  end;

  -- 9. pickups
  begin
    execute 'delete from public.pickups where coalesce(source_file,'''') = ''BE_MasterData_April.xlsx'' or coalesce(source_file,'''') ilike ''%demo%'' or pickup_code like ''PU-DEMO%'' or merchant_name in (''Golden Shop'',''Silver Store'',''Diamond Mart'',''Tech Store Myanmar'',''Fashion Hub'',''Book World'',''Demo Merchant'')';
  exception when others then null;
  end;

  -- 10. merchants
  begin
    execute 'delete from public.merchants where coalesce(name,'''') ilike ''%demo%'' or name in (''Golden Shop'',''Silver Store'',''Diamond Mart'',''Tech Store Myanmar'',''Fashion Hub'',''Book World'',''Demo Merchant'')';
  exception when others then null;
  end;

  -- 11. merchants_2026_04_24 (Rider App)
  begin
    execute 'delete from public.merchants_2026_04_24 where coalesce(name,'''') ilike ''%demo%'' or name in (''Golden Shop'',''Silver Store'',''Diamond Mart'',''Tech Store Myanmar'',''Fashion Hub'',''Book World'',''Demo Merchant'')';
  exception when others then null;
  end;

  -- 12. staff_master
  begin
    execute 'delete from public.staff_master where coalesce(email,'''') ilike ''%demo%'' or coalesce(email,'''') ilike ''%.demo@britiumexpress.com'' or coalesce(name,'''') ilike ''Demo %'' or coalesce(name,'''') ilike ''% demo''';
  exception when others then null;
  end;

  -- 13. rider_notifications
  begin
    execute 'delete from public.rider_notifications rn using public.profiles p where rn.user_id = p.id and (p.email ilike ''%.demo@britiumexpress.com'' or p.email ilike ''%demo%'' or p.full_name ilike ''Demo %'')';
  exception when others then null;
  end;

  -- 14. profiles
  begin
    execute 'update public.profiles set status = ''inactive'', is_active = false, is_approved = false where email ilike ''%.demo@britiumexpress.com'' or email ilike ''%demo%'' or full_name ilike ''Demo %''';
  exception when others then null;
  end;

end $$;
