on conflict (pickup_code) do update set
  pickup_date = excluded.pickup_date,
  merchant_name = excluded.merchant_name,
  pickup_by = excluded.pickup_by,
  total_items = excluded.total_items,
  total_cod = excluded.total_cod,
  total_delivery_fee = excluded.total_delivery_fee,
  total_actual_collect = excluded.total_actual_collect,
  status = excluded.status,
  source_file = excluded.source_file,
  updated_at = now();


update public.pickups p
set merchant_id = m.id
from public.merchants m
where p.merchant_name = m.name and p.source_file = 'BE_MasterData_April.xlsx';

insert into public.pickups_2026_04_24 (
  pickup_id, pickup_date, merchant_id, expected_way_count, calculated_tariff, pickup_status, remarks
)
select p.pickup_code, p.pickup_date, m26.id, p.total_items, p.total_delivery_fee, 'WEIGHING',
       'Imported from BE_MasterData_April.xlsx'
from public.pickups p
left join public.merchants_2026_04_24 m26 on m26.name = p.merchant_name
where p.source_file = 'BE_MasterData_April.xlsx'
on conflict (pickup_id) do update set
  pickup_date = excluded.pickup_date,
  merchant_id = excluded.merchant_id,
  expected_way_count = excluded.expected_way_count,
  calculated_tariff = excluded.calculated_tariff,
  pickup_status = excluded.pickup_status,
  updated_at = now();


-- Upsert shipments from BE_MasterData_April.xlsx. Existing matching tracking_no rows are updated in place.
insert into public.shipments (
  tracking_no, customer_name, customer_phone, pickup_address, delivery_address,
  township, zone, status, cod_amount, service_type, weight, merchant_name,
  pickup_code, pickup_date, item_price, delivery_fee_os, delivery_fee_max,
  surcharge, actual_collect, destination, pickup_by, excel_status, notes,
