on conflict (tracking_no) do update set
  customer_name = excluded.customer_name,
  customer_phone = excluded.customer_phone,
  delivery_address = excluded.delivery_address,
  township = excluded.township,
  zone = excluded.zone,
  status = excluded.status,
  cod_amount = excluded.cod_amount,
  service_type = excluded.service_type,
  weight = excluded.weight,
  merchant_name = excluded.merchant_name,
  pickup_code = excluded.pickup_code,
  pickup_date = excluded.pickup_date,
  item_price = excluded.item_price,
  delivery_fee_os = excluded.delivery_fee_os,
  delivery_fee_max = excluded.delivery_fee_max,
  surcharge = excluded.surcharge,
  actual_collect = excluded.actual_collect,
  destination = excluded.destination,
  pickup_by = excluded.pickup_by,
  excel_status = excluded.excel_status,
  notes = excluded.notes,
  source_file = excluded.source_file,
  updated_at = now();

