on conflict (tracking_no) do update set
  customer_name = excluded.customer_name,
  customer_phone = excluded.customer_phone,
  delivery_address = excluded.delivery_address,
  township = excluded.township,
  zone = excluded.zone,
  status = excluded.status,
  cod_amount = excluded.cod_amount,
  service_type = excluded.service_type,
  weight = excluded.weight,
  merchant_name = excluded.merchant_name,
  pickup_code = excluded.pickup_code,
  pickup_date = excluded.pickup_date,
  item_price = excluded.item_price,
  delivery_fee_os = excluded.delivery_fee_os,
  delivery_fee_max = excluded.delivery_fee_max,
  surcharge = excluded.surcharge,
  actual_collect = excluded.actual_collect,
  destination = excluded.destination,
  pickup_by = excluded.pickup_by,
  excel_status = excluded.excel_status,
  notes = excluded.notes,
  source_file = excluded.source_file,
  updated_at = now();


update public.shipments s
set pickup_id = p.id,
    merchant_id = m.id
from public.pickups p
left join public.merchants m on m.name = p.merchant_name
where s.pickup_code = p.pickup_code
  and s.source_file = 'BE_MasterData_April.xlsx';

insert into public.cod_collections (shipment_id, tracking_no, rider_name, amount, status, collected_at)
select s.id, s.tracking_no, s.pickup_by, coalesce(s.actual_collect, s.cod_amount, 0),
       'pending',
       case when s.status = 'delivered' then coalesce(s.delivered_at, s.actual_delivery_date, now()) else null end
from public.shipments s
where s.source_file = 'BE_MasterData_April.xlsx'
  and coalesce(s.actual_collect, s.cod_amount, 0) > 0
on conflict do nothing;

insert into public.delivery_process_events (shipment_id, tracking_no, to_status, event_type, channel, notes, metadata)
select s.id, s.tracking_no, s.status, 'imported', 'data_entry_portal',
       'Imported from BE_MasterData_April.xlsx',
       jsonb_build_object('merchant', s.merchant_name, 'pickup_code', s.pickup_code, 'excel_status', s.excel_status)
from public.shipments s
where s.source_file = 'BE_MasterData_April.xlsx'
on conflict do nothing;

-- Default module permissions.
insert into public.portal_authorizations (role_code, module_code, can_read, can_create, can_update, can_delete) values
  ('superadmin','*',true,true,true,true),
  ('admin','*',true,true,true,true),
  ('ops','delivery_workflow',true,true,true,false),
  ('dispatch','delivery_dispatch',true,true,true,false),
  ('data_entry','data_entry',true,true,true,false),
  ('data_entry','pickups',true,true,true,false),
  ('warehouse','warehouse',true,true,true,false),
  ('finance','cod_settlement',true,false,true,false),
  ('cs','customer_service',true,true,true,false),
  ('merchant','merchant_portal',true,false,false,false),
  ('customer','customer_portal',true,false,false,false),
  ('rider','rider_app',true,false,true,false),
  ('driver','driver_app',true,false,true,false),
  ('helper','helper_app',true,false,true,false)
on conflict (role_code, module_code) do update set
  can_read = excluded.can_read,
  can_create = excluded.can_create,
  can_update = excluded.can_update,
  can_delete = excluded.can_delete;

-- ---------- RLS ----------
alter table public.merchants enable row level security;
alter table public.townships enable row level security;
alter table public.staff_master enable row level security;
alter table public.pickups enable row level security;
alter table public.delivery_process_events enable row level security;
alter table public.portal_authorizations enable row level security;

drop policy if exists "be_master_read" on public.merchants;
create policy "be_master_read" on public.merchants for select to authenticated using (true);
drop policy if exists "be_master_admin_write" on public.merchants;
create policy "be_master_admin_write" on public.merchants for all to authenticated using (public.be_has_role(array['superadmin','admin','ops','data_entry'])) with check (public.be_has_role(array['superadmin','admin','ops','data_entry']));

drop policy if exists "be_township_read" on public.townships;
create policy "be_township_read" on public.townships for select to authenticated using (true);
drop policy if exists "be_township_admin_write" on public.townships;
create policy "be_township_admin_write" on public.townships for all to authenticated using (public.be_has_role(array['superadmin','admin','ops'])) with check (public.be_has_role(array['superadmin','admin','ops']));

drop policy if exists "be_staff_read" on public.staff_master;
create policy "be_staff_read" on public.staff_master for select to authenticated using (public.be_has_role(array['superadmin','admin','ops','dispatch','warehouse','finance','data_entry']));
drop policy if exists "be_staff_admin_write" on public.staff_master;
create policy "be_staff_admin_write" on public.staff_master for all to authenticated using (public.be_has_role(array['superadmin','admin'])) with check (public.be_has_role(array['superadmin','admin']));

drop policy if exists "be_pickups_read" on public.pickups;
create policy "be_pickups_read" on public.pickups for select to authenticated using (
  public.be_has_role(array['superadmin','admin','ops','dispatch','warehouse','finance','cs','data_entry'])
  or exists (select 1 from public.profiles p where p.id = auth.uid() and p.full_name = pickups.pickup_by)
);
drop policy if exists "be_pickups_write" on public.pickups;
create policy "be_pickups_write" on public.pickups for all to authenticated using (public.be_has_role(array['superadmin','admin','ops','dispatch','data_entry'])) with check (public.be_has_role(array['superadmin','admin','ops','dispatch','data_entry']));

drop policy if exists "be_shipments_read" on public.shipments;
create policy "be_shipments_read" on public.shipments for select to authenticated using (
  public.be_has_role(array['superadmin','admin','ops','dispatch','warehouse','finance','cs','data_entry'])
  or assigned_to = auth.uid()
  or exists (select 1 from public.profiles p where p.id = auth.uid() and p.full_name = shipments.pickup_by)
);
drop policy if exists "be_shipments_write" on public.shipments;
create policy "be_shipments_write" on public.shipments for all to authenticated using (
  public.be_has_role(array['superadmin','admin','ops','dispatch','warehouse','data_entry'])
  or assigned_to = auth.uid()
) with check (
  public.be_has_role(array['superadmin','admin','ops','dispatch','warehouse','data_entry'])
  or assigned_to = auth.uid()
);

drop policy if exists "be_events_read" on public.delivery_process_events;
create policy "be_events_read" on public.delivery_process_events for select to authenticated using (public.be_has_role(array['superadmin','admin','ops','dispatch','warehouse','finance','cs','data_entry']));
drop policy if exists "be_events_insert" on public.delivery_process_events;
create policy "be_events_insert" on public.delivery_process_events for insert to authenticated with check (auth.role() = 'authenticated');

drop policy if exists "be_authorizations_admin" on public.portal_authorizations;
create policy "be_authorizations_admin" on public.portal_authorizations for all to authenticated using (public.be_has_role(array['superadmin','admin'])) with check (public.be_has_role(array['superadmin','admin']));

-- Rider app suffixed table policies.
alter table public.merchants_2026_04_24 enable row level security;
alter table public.townships_2026_04_24 enable row level security;
alter table public.tariffs_2026_04_24 enable row level security;
alter table public.pickups_2026_04_24 enable row level security;
alter table public.pickup_attachments_2026_04_24 enable row level security;

drop policy if exists "be_rider_master_read_merchants" on public.merchants_2026_04_24;
create policy "be_rider_master_read_merchants" on public.merchants_2026_04_24 for select to authenticated using (true);
drop policy if exists "be_rider_master_read_townships" on public.townships_2026_04_24;
create policy "be_rider_master_read_townships" on public.townships_2026_04_24 for select to authenticated using (true);
drop policy if exists "be_rider_master_read_tariffs" on public.tariffs_2026_04_24;
create policy "be_rider_master_read_tariffs" on public.tariffs_2026_04_24 for select to authenticated using (true);

drop policy if exists "be_rider_pickups_all" on public.pickups_2026_04_24;
create policy "be_rider_pickups_all" on public.pickups_2026_04_24 for all to authenticated using (
  public.be_has_role(array['superadmin','admin','ops','dispatch','data_entry','rider','driver','helper'])
  or rider_id = auth.uid()
) with check (
  public.be_has_role(array['superadmin','admin','ops','dispatch','data_entry','rider','driver','helper'])
  or rider_id = auth.uid()
);

drop policy if exists "be_rider_attachments_all" on public.pickup_attachments_2026_04_24;
create policy "be_rider_attachments_all" on public.pickup_attachments_2026_04_24 for all to authenticated using (
  public.be_has_role(array['superadmin','admin','ops','dispatch','data_entry','rider','driver','helper'])
  or uploaded_by = auth.uid()
) with check (
  public.be_has_role(array['superadmin','admin','ops','dispatch','data_entry','rider','driver','helper'])
  or uploaded_by = auth.uid()
);

